// OpenShellHandler is an implementation of the openshell.v1.OpenShell service.
type OpenShellHandler interface {
	// Check the health of the service.
	Health(context.Context, *connect.Request[openshellv1.HealthRequest]) (*connect.Response[openshellv1.HealthResponse], error)
	// Return the authenticated caller identity established by the gateway.
	GetCurrentUser(context.Context, *connect.Request[openshellv1.GetCurrentUserRequest]) (*connect.Response[openshellv1.GetCurrentUserResponse], error)
	// Fetch elevated live gateway runtime metadata.
	GetGatewayInfo(context.Context, *connect.Request[openshellv1.GetGatewayInfoRequest]) (*connect.Response[openshellv1.GetGatewayInfoResponse], error)
	// Create a new sandbox.
	CreateSandbox(context.Context, *connect.Request[openshellv1.CreateSandboxRequest]) (*connect.Response[openshellv1.SandboxResponse], error)
	// Allocate a gateway-owned staging slot for a local rootfs tar archive.
	//
	// The gateway creates a request-scoped directory inside the compute driver's
	// staging root and returns an opaque single-use token plus the absolute path
	// the client must write the archive to. The token is then passed as
	// `template.driver_config.<driver>.rootfs_tar_staging_token` on
	// CreateSandbox; callers never name a filesystem path themselves. Only a
	// client sharing the gateway's filesystem can complete the upload.
	BeginRootfsTarStaging(context.Context, *connect.Request[openshellv1.BeginRootfsTarStagingRequest]) (*connect.Response[openshellv1.BeginRootfsTarStagingResponse], error)
	// Fetch a sandbox by name.
	GetSandbox(context.Context, *connect.Request[openshellv1.GetSandboxRequest]) (*connect.Response[openshellv1.SandboxResponse], error)
	// List sandboxes.
	ListSandboxes(context.Context, *connect.Request[openshellv1.ListSandboxesRequest]) (*connect.Response[openshellv1.ListSandboxesResponse], error)
	// Create a reusable sandbox workload template.
	CreateSandboxTemplate(context.Context, *connect.Request[openshellv1.CreateSandboxTemplateRequest]) (*connect.Response[openshellv1.SandboxTemplateResponse], error)
	// Fetch a reusable sandbox workload template by name.
	GetSandboxTemplate(context.Context, *connect.Request[openshellv1.GetSandboxTemplateRequest]) (*connect.Response[openshellv1.SandboxTemplateResponse], error)
	// List reusable sandbox workload templates.
	ListSandboxTemplates(context.Context, *connect.Request[openshellv1.ListSandboxTemplatesRequest]) (*connect.Response[openshellv1.ListSandboxTemplatesResponse], error)
	// Delete a reusable sandbox workload template by name.
	DeleteSandboxTemplate(context.Context, *connect.Request[openshellv1.DeleteSandboxTemplateRequest]) (*connect.Response[openshellv1.DeleteSandboxTemplateResponse], error)
	// List provider records attached to a sandbox.
	ListSandboxProviders(context.Context, *connect.Request[openshellv1.ListSandboxProvidersRequest]) (*connect.Response[openshellv1.ListSandboxProvidersResponse], error)
	// Attach a provider record to an existing sandbox.
	AttachSandboxProvider(context.Context, *connect.Request[openshellv1.AttachSandboxProviderRequest]) (*connect.Response[openshellv1.AttachSandboxProviderResponse], error)
	// Detach a provider record from an existing sandbox.
	DetachSandboxProvider(context.Context, *connect.Request[openshellv1.DetachSandboxProviderRequest]) (*connect.Response[openshellv1.DetachSandboxProviderResponse], error)
	// Inspect the installed authority for one sandbox provider mutation.
	GetSandboxProviderStatus(context.Context, *connect.Request[openshellv1.GetSandboxProviderStatusRequest]) (*connect.Response[openshellv1.GetSandboxProviderStatusResponse], error)
	// Delete a sandbox by name.
	DeleteSandbox(context.Context, *connect.Request[openshellv1.DeleteSandboxRequest]) (*connect.Response[openshellv1.DeleteSandboxResponse], error)
	// Stop a sandbox while retaining its persistent state.
	StopSandbox(context.Context, *connect.Request[openshellv1.StopSandboxRequest]) (*connect.Response[openshellv1.SandboxResponse], error)
	// Start a previously stopped sandbox.
	StartSandbox(context.Context, *connect.Request[openshellv1.StartSandboxRequest]) (*connect.Response[openshellv1.SandboxResponse], error)
	// Create a short-lived SSH session for a sandbox.
	CreateSshSession(context.Context, *connect.Request[openshellv1.CreateSshSessionRequest]) (*connect.Response[openshellv1.CreateSshSessionResponse], error)
	// Create or update a sandbox HTTP service endpoint for local routing.
	ExposeService(context.Context, *connect.Request[openshellv1.ExposeServiceRequest]) (*connect.Response[openshellv1.ServiceEndpointResponse], error)
	// Fetch one sandbox HTTP service endpoint.
	GetService(context.Context, *connect.Request[openshellv1.GetServiceRequest]) (*connect.Response[openshellv1.ServiceEndpointResponse], error)
	// List sandbox HTTP service endpoints.
	ListServices(context.Context, *connect.Request[openshellv1.ListServicesRequest]) (*connect.Response[openshellv1.ListServicesResponse], error)
	// Delete one sandbox HTTP service endpoint.
	DeleteService(context.Context, *connect.Request[openshellv1.DeleteServiceRequest]) (*connect.Response[openshellv1.DeleteServiceResponse], error)
	// Revoke a previously issued SSH session.
	RevokeSshSession(context.Context, *connect.Request[openshellv1.RevokeSshSessionRequest]) (*connect.Response[openshellv1.RevokeSshSessionResponse], error)
	// Execute a command in a ready sandbox and stream output.
	ExecSandbox(context.Context, *connect.Request[openshellv1.ExecSandboxRequest], *connect.ServerStream[openshellv1.ExecSandboxEvent]) error
	// Forward one CLI-side TCP connection to a loopback TCP target in a sandbox.
	ForwardTcp(context.Context, *connect.BidiStream[openshellv1.TcpForwardFrame, openshellv1.TcpForwardFrame]) error
	// Execute an interactive command with bidirectional stdin/stdout streaming.
	// The first client message MUST carry an ExecSandboxInput with the start
	// variant. Subsequent messages carry stdin bytes or window resize events.
	ExecSandboxInteractive(context.Context, *connect.BidiStream[openshellv1.ExecSandboxInput, openshellv1.ExecSandboxEvent]) error
	// Create a provider.
	CreateProvider(context.Context, *connect.Request[openshellv1.CreateProviderRequest]) (*connect.Response[openshellv1.ProviderResponse], error)
	// Fetch a provider by name.
	GetProvider(context.Context, *connect.Request[openshellv1.GetProviderRequest]) (*connect.Response[openshellv1.ProviderResponse], error)
	// List providers.
	ListProviders(context.Context, *connect.Request[openshellv1.ListProvidersRequest]) (*connect.Response[openshellv1.ListProvidersResponse], error)
	// List available provider type profiles.
	ListProviderProfiles(context.Context, *connect.Request[openshellv1.ListProviderProfilesRequest]) (*connect.Response[openshellv1.ListProviderProfilesResponse], error)
	// Fetch one provider type profile by id.
	GetProviderProfile(context.Context, *connect.Request[openshellv1.GetProviderProfileRequest]) (*connect.Response[openshellv1.ProviderProfileResponse], error)
	// Import custom provider type profiles.
	ImportProviderProfiles(context.Context, *connect.Request[openshellv1.ImportProviderProfilesRequest]) (*connect.Response[openshellv1.ImportProviderProfilesResponse], error)
	// Update an existing custom provider type profile.
	UpdateProviderProfiles(context.Context, *connect.Request[openshellv1.UpdateProviderProfilesRequest]) (*connect.Response[openshellv1.UpdateProviderProfilesResponse], error)
	// Validate provider type profiles without registering them.
	LintProviderProfiles(context.Context, *connect.Request[openshellv1.LintProviderProfilesRequest]) (*connect.Response[openshellv1.LintProviderProfilesResponse], error)
	// Update an existing provider by name.
	UpdateProvider(context.Context, *connect.Request[openshellv1.UpdateProviderRequest]) (*connect.Response[openshellv1.ProviderResponse], error)
	// Fetch refresh status for one provider or provider credential.
	GetProviderRefreshStatus(context.Context, *connect.Request[openshellv1.GetProviderRefreshStatusRequest]) (*connect.Response[openshellv1.GetProviderRefreshStatusResponse], error)
	// Configure gateway-owned refresh material for one provider credential.
	ConfigureProviderRefresh(context.Context, *connect.Request[openshellv1.ConfigureProviderRefreshRequest]) (*connect.Response[openshellv1.ConfigureProviderRefreshResponse], error)
	// Record a gateway-owned refresh request for one provider credential.
	RotateProviderCredential(context.Context, *connect.Request[openshellv1.RotateProviderCredentialRequest]) (*connect.Response[openshellv1.RotateProviderCredentialResponse], error)
	// Delete gateway-owned refresh configuration for one provider credential.
	DeleteProviderRefresh(context.Context, *connect.Request[openshellv1.DeleteProviderRefreshRequest]) (*connect.Response[openshellv1.DeleteProviderRefreshResponse], error)
	// Delete a provider by name.
	DeleteProvider(context.Context, *connect.Request[openshellv1.DeleteProviderRequest]) (*connect.Response[openshellv1.DeleteProviderResponse], error)
	// Delete a custom provider type profile by id.
	DeleteProviderProfile(context.Context, *connect.Request[openshellv1.DeleteProviderProfileRequest]) (*connect.Response[openshellv1.DeleteProviderProfileResponse], error)
	// Get sandbox settings by id (called by sandbox entrypoint and poll loop).
	GetSandboxConfig(context.Context, *connect.Request[sandboxv1.GetSandboxConfigRequest]) (*connect.Response[sandboxv1.GetSandboxConfigResponse], error)
	// Get gateway-global settings (read-only runtime configuration; any
	// authenticated user may read these without requiring Platform Admin).
	//
	// Scope-only (no role): scopes are granted by the IdP at token issuance,
	// orthogonal to workspace membership. Deployments that enable scope
	// enforcement configure the IdP to grant config:read (or openshell:all)
	// to all sandbox users, so this does not block least-privilege flows.
	GetGatewayConfig(context.Context, *connect.Request[sandboxv1.GetGatewayConfigRequest]) (*connect.Response[sandboxv1.GetGatewayConfigResponse], error)
	// Update settings or policy at sandbox or global scope.
	UpdateConfig(context.Context, *connect.Request[openshellv1.UpdateConfigRequest]) (*connect.Response[openshellv1.UpdateConfigResponse], error)
	// Get the load status of a specific policy version.
	GetSandboxPolicyStatus(context.Context, *connect.Request[openshellv1.GetSandboxPolicyStatusRequest]) (*connect.Response[openshellv1.GetSandboxPolicyStatusResponse], error)
	// List policy history for a sandbox.
	ListSandboxPolicies(context.Context, *connect.Request[openshellv1.ListSandboxPoliciesRequest]) (*connect.Response[openshellv1.ListSandboxPoliciesResponse], error)
	// Report policy load result (called by sandbox after reload attempt).
	ReportPolicyStatus(context.Context, *connect.Request[openshellv1.ReportPolicyStatusRequest]) (*connect.Response[openshellv1.ReportPolicyStatusResponse], error)
	// Replace the gateway's observed tool server endpoint status for one sandbox.
	ReportEndpointStatus(context.Context, *connect.Request[openshellv1.ReportEndpointStatusRequest]) (*connect.Response[openshellv1.ReportEndpointStatusResponse], error)
	// Report installed provider state for the current ConnectSupervisor session.
	// Replacing or losing that session invalidates its observations.
	ReportProviderReadiness(context.Context, *connect.Request[openshellv1.ReportProviderReadinessRequest]) (*connect.Response[openshellv1.ReportProviderReadinessResponse], error)
	// Register startup and acknowledge an exact validated runtime configuration.
	ReportSandboxConfiguration(context.Context, *connect.Request[openshellv1.ReportSandboxConfigurationRequest]) (*connect.Response[openshellv1.ReportSandboxConfigurationResponse], error)
	// Get provider environment for a sandbox (called by sandbox supervisor at startup).
	GetSandboxProviderEnvironment(context.Context, *connect.Request[openshellv1.GetSandboxProviderEnvironmentRequest]) (*connect.Response[openshellv1.GetSandboxProviderEnvironmentResponse], error)
	// Exchange a stored provider subject token for an intermediate token scoped
	// to the calling supervisor's SPIFFE identity.
	ExchangeProviderSubjectToken(context.Context, *connect.Request[openshellv1.ExchangeProviderSubjectTokenRequest]) (*connect.Response[openshellv1.ExchangeProviderSubjectTokenResponse], error)
	// Fetch recent sandbox logs (one-shot).
	GetSandboxLogs(context.Context, *connect.Request[openshellv1.GetSandboxLogsRequest]) (*connect.Response[openshellv1.GetSandboxLogsResponse], error)
	// Push sandbox supervisor logs to the server (client-streaming).
	PushSandboxLogs(context.Context, *connect.ClientStream[openshellv1.PushSandboxLogsRequest]) (*connect.Response[openshellv1.PushSandboxLogsResponse], error)
	// Persistent supervisor-to-gateway session (bidirectional streaming).
	//
	// The supervisor opens this stream at startup and keeps it alive for the
	// sandbox lifetime. The gateway uses it to coordinate relay channels for
	// SSH connect, ExecSandbox, and targetable sandbox services. Raw service
	// bytes flow over RelayStream calls (separate HTTP/2 streams on the same
	// connection), not over this stream.
	ConnectSupervisor(context.Context, *connect.BidiStream[openshellv1.SupervisorMessage, openshellv1.GatewayMessage]) error
	// Persist the canonical main process result before the supervisor exits.
	ReportMainProcessExit(context.Context, *connect.Request[openshellv1.ReportMainProcessExitRequest]) (*connect.Response[openshellv1.ReportMainProcessExitResponse], error)
	// Confirm that foreground terminal delivery completed naturally.
	FinalizeMainProcessExit(context.Context, *connect.Request[openshellv1.FinalizeMainProcessExitRequest]) (*connect.Response[openshellv1.FinalizeMainProcessExitResponse], error)
	// Raw byte relay between supervisor and gateway.
	//
	// The supervisor initiates this call after receiving a RelayOpen message
	// on its ConnectSupervisor stream. The first RelayFrame carries a
	// RelayInit with the channel_id to associate the new HTTP/2 stream with
	// the pending relay slot on the gateway. Subsequent frames carry raw bytes in either
	// direction between the gateway-side waiter (ForwardTcp / exec handler)
	// and the supervisor-side target bridge.
	//
	// This rides the same TCP+TLS+HTTP/2 connection as ConnectSupervisor —
	// no new TLS handshake, no reverse HTTP CONNECT.
	RelayStream(context.Context, *connect.BidiStream[openshellv1.RelayFrame, openshellv1.RelayFrame]) error
	// Internal gateway-to-gateway relay forwarding.
	//
	// A gateway replica that receives a user request for a sandbox whose
	// supervisor session is owned by a different replica opens this stream to the
	// owner. The first frame carries PeerRelayInit; subsequent frames carry raw
	// bytes in either direction. This RPC is authenticated as a gateway peer, not
	// as a user or sandbox supervisor.
	PeerRelay(context.Context, *connect.BidiStream[openshellv1.PeerRelayFrame, openshellv1.PeerRelayFrame]) error
	// Internal gateway-to-owner forwarding for supervisor-bound state.
	PeerReportProviderReadiness(context.Context, *connect.Request[openshellv1.ReportProviderReadinessRequest]) (*connect.Response[openshellv1.ReportProviderReadinessResponse], error)
	PeerReportEndpointStatus(context.Context, *connect.Request[openshellv1.ReportEndpointStatusRequest]) (*connect.Response[openshellv1.ReportEndpointStatusResponse], error)
	PeerGetSandboxProviderStatus(context.Context, *connect.Request[openshellv1.GetSandboxProviderStatusRequest]) (*connect.Response[openshellv1.GetSandboxProviderStatusResponse], error)
	// Watch a sandbox and stream updates.
	//
	// This stream can include:
	// - Sandbox status snapshots (phase/status)
	// - OpenShell server process logs correlated by sandbox_id
	// - Platform events correlated to the sandbox
	WatchSandbox(context.Context, *connect.Request[openshellv1.WatchSandboxRequest], *connect.ServerStream[openshellv1.SandboxStreamEvent]) error
	// Submit denial analysis results from sandbox (summaries + proposed chunks).
	SubmitPolicyAnalysis(context.Context, *connect.Request[openshellv1.SubmitPolicyAnalysisRequest]) (*connect.Response[openshellv1.SubmitPolicyAnalysisResponse], error)
	// Get draft policy recommendations for a sandbox.
	GetDraftPolicy(context.Context, *connect.Request[openshellv1.GetDraftPolicyRequest]) (*connect.Response[openshellv1.GetDraftPolicyResponse], error)
	// Approve a single draft policy chunk (merges into active policy).
	ApproveDraftChunk(context.Context, *connect.Request[openshellv1.ApproveDraftChunkRequest]) (*connect.Response[openshellv1.ApproveDraftChunkResponse], error)
	// Reject a single draft policy chunk.
	RejectDraftChunk(context.Context, *connect.Request[openshellv1.RejectDraftChunkRequest]) (*connect.Response[openshellv1.RejectDraftChunkResponse], error)
	// Approve all pending draft chunks (skips security-flagged unless forced).
	ApproveAllDraftChunks(context.Context, *connect.Request[openshellv1.ApproveAllDraftChunksRequest]) (*connect.Response[openshellv1.ApproveAllDraftChunksResponse], error)
	// Edit a pending draft chunk in-place (e.g. narrow allowed_ips).
	EditDraftChunk(context.Context, *connect.Request[openshellv1.EditDraftChunkRequest]) (*connect.Response[openshellv1.EditDraftChunkResponse], error)
	// Reverse an approval (remove merged rule from active policy).
	UndoDraftChunk(context.Context, *connect.Request[openshellv1.UndoDraftChunkRequest]) (*connect.Response[openshellv1.UndoDraftChunkResponse], error)
	// Clear all pending draft chunks for a sandbox.
	ClearDraftChunks(context.Context, *connect.Request[openshellv1.ClearDraftChunksRequest]) (*connect.Response[openshellv1.ClearDraftChunksResponse], error)
	// Get decision history for a sandbox's draft policy.
	GetDraftHistory(context.Context, *connect.Request[openshellv1.GetDraftHistoryRequest]) (*connect.Response[openshellv1.GetDraftHistoryResponse], error)
	// Exchange a sandbox-bootstrap credential (e.g. a Kubernetes projected
	// ServiceAccount token) for a gateway-minted JWT bound to the calling
	// sandbox's UUID. Used by the Kubernetes driver path; singleplayer
	// drivers receive the gateway JWT directly from the create-sandbox flow
	// and never call this RPC.
	IssueSandboxToken(context.Context, *connect.Request[openshellv1.IssueSandboxTokenRequest]) (*connect.Response[openshellv1.IssueSandboxTokenResponse], error)
	// Renew the calling sandbox's gateway JWT. Older tokens remain valid
	// until their own expiry; deployments should keep token TTLs short to
	// bound replay exposure. The supervisor calls this from a background
	// task at ~80% of the token's lifetime; the new token is cached in
	// memory only — the on-disk bootstrap file is intentionally not
	// rewritten.
	RefreshSandboxToken(context.Context, *connect.Request[openshellv1.RefreshSandboxTokenRequest]) (*connect.Response[openshellv1.RefreshSandboxTokenResponse], error)
	// Create a workspace.
	CreateWorkspace(context.Context, *connect.Request[openshellv1.CreateWorkspaceRequest]) (*connect.Response[openshellv1.CreateWorkspaceResponse], error)
	// Fetch a workspace by name.
	GetWorkspace(context.Context, *connect.Request[openshellv1.GetWorkspaceRequest]) (*connect.Response[openshellv1.GetWorkspaceResponse], error)
	// List workspaces.
	ListWorkspaces(context.Context, *connect.Request[openshellv1.ListWorkspacesRequest]) (*connect.Response[openshellv1.ListWorkspacesResponse], error)
	// Delete a workspace by name.
	DeleteWorkspace(context.Context, *connect.Request[openshellv1.DeleteWorkspaceRequest]) (*connect.Response[openshellv1.DeleteWorkspaceResponse], error)
	// Add a member to a workspace.
	AddWorkspaceMember(context.Context, *connect.Request[openshellv1.AddWorkspaceMemberRequest]) (*connect.Response[openshellv1.AddWorkspaceMemberResponse], error)
	// Remove a member from a workspace.
	RemoveWorkspaceMember(context.Context, *connect.Request[openshellv1.RemoveWorkspaceMemberRequest]) (*connect.Response[openshellv1.RemoveWorkspaceMemberResponse], error)
	// List members of a workspace.
	ListWorkspaceMembers(context.Context, *connect.Request[openshellv1.ListWorkspaceMembersRequest]) (*connect.Response[openshellv1.ListWorkspaceMembersResponse], error)
}

